async function dispatchActionInvoke(request, deps) {
  if (request.verb === SEND_VERB) {
    return dispatchSend(request, deps);
  }
  if (request.verb === OLDER_VERB || request.verb === NEWER_VERB || request.verb === FULL_HISTORY_VERB) {
    return dispatchPage(request, deps);
  }
  if (request.verb === FLEET_VERB || request.verb === REPLY_VERB || request.verb === LOG_VERB || request.verb === OPEN_CHAT_VERB) {
    let command;
    if (request.verb === FLEET_VERB) {
      command = { kind: "fleet" };
    } else {
      const chatId = readString(request.data, "chatId");
      if (chatId === null) {
        return {
          card: buildUsageCard("That button was missing its chat id."),
          acted: false
        };
      }
      command = request.verb === REPLY_VERB || request.verb === OPEN_CHAT_VERB ? { kind: "chat", chatId } : { kind: "log", chatId, offset: 0 };
    }
    const cards = await dispatchCommand(
      command,
      request.conversationId,
      deps
    );
    const card2 = cards[0];
    if (card2 === void 0) {
      return {
        card: buildUsageCard("That didn't return anything to show."),
        acted: false
      };
    }
    return { card: card2, acted: true };
  }
  if (request.verb !== APPROVE_VERB && request.verb !== REJECT_VERB) {
    return {
      card: buildUsageCard(`Unknown card action "${request.verb}".`),
      acted: false
    };
  }
  const approvalId = readString(request.data, "approvalId");
  if (approvalId === null) {
    return {
      card: buildUsageCard("That button was missing its approval id."),
      acted: false
    };
  }
  const identity = await deps.resolvePrincipal();
  if (identity.kind === "unavailable") {
    return {
      card: buildIdentityUnavailableCard(identity.reason),
      acted: false
    };
  }
  const decision = request.verb === APPROVE_VERB ? { kind: "approve" } : { kind: "reject", reason: readString(request.data, "rejectReason") };
  const result = await submitApprovalDecision(
    identity.principal,
    request.conversationId,
    approvalId,
    decision,
    deps
  );
  switch (result.kind) {
    case "ok":
      return {
        card: buildActionOutcomeCard(result.outcome, decision.kind),
        acted: true
      };
    case "principal_refused":
      return { card: buildPrincipalRefusedCard(result.reason), acted: false };
    case "epic_not_bound":
      return { card: buildEpicNotBoundCard(), acted: false };
    case "bridge_unavailable":
      return {
        card: buildBridgeUnavailableCard(result.reason, result.detail),
        acted: false
      };
  }
}

// src/intake/mention.ts
function stripMentions(rawText, entities, botId) {
  let text2 = rawText;
  let strippedByEntity = false;
  let sawMentionEntity = false;
  for (const entity of entities ?? []) {
    if (entity.type.toLowerCase() !== "mention") continue;
    if (entity.text === void 0 || entity.text === "") continue;
    sawMentionEntity = true;
    if (!text2.includes(entity.text)) continue;
    const addressesBot = botId === void 0 || entity.mentioned?.id === void 0 || entity.mentioned.id === botId;
    if (addressesBot) {
      text2 = text2.split(entity.text).join(" ");
    } else {
      text2 = text2.split(entity.text).join(entity.mentioned?.name ?? " ");
    }
    strippedByEntity = true;
  }
  let usedFallback = false;
  if (!sawMentionEntity) {
    const beforeFallback = text2;
    text2 = text2.replace(/<at>[^<]*<\/at>/gi, " ");
    usedFallback = text2 !== beforeFallback;
  }
  return {
    text: text2.trim().replace(/\s+/g, " "),
    strippedByEntity,
    usedFallback
  };
}

